var _s2 = SLP.books.find(function(b){ return b.id === "2-sam"; });
if (!_s2) throw new Error("data/canon.js must load before ot-10-2samuel.js");
(_s2.chapters = _s2.chapters || []).push(
{ n:1, summary:"Word reaches David at Ziklag: Saul and Jonathan are dead. A messenger, an Amalekite, claims he mercifully killed the wounded king on mount Gilboa and brings David the crown and bracelet. David and his men tear their clothes, weep, and fast until evening for Saul, for Jonathan, and for the people of the LORD fallen by the sword. Then David has the messenger executed for boasting that he slew the LORD's anointed. David's lament over Saul and Jonathan, written down and taught to the children of Judah, mourns Israel's fallen glory, begs that Philistine cities not hear the news and rejoice, curses the mountains of Gilboa, praises the bravery of the king and his son in life and death, and closes with David's own heartbreak for Jonathan, whose love he calls wonderful, passing the love of women. Twice the refrain falls: how are the mighty fallen!",
  context:"David is still at Ziklag when the news of Saul's fall on mount Gilboa reaches him, and the nation's grief becomes a lament taught to the children of Judah.",
  keyVerses:[
    { ref:"2 Samuel 1:14", text:"And David said unto him, How wast thou not afraid to stretch forth thine hand to destroy the LORD's anointed?" },
    { ref:"2 Samuel 1:19", text:"The beauty of Israel is slain upon thy high places: how are the mighty fallen!" },
    { ref:"2 Samuel 1:26", text:"I am distressed for thee, my brother Jonathan: very pleasant hast thou been unto me: thy love to me was wonderful, passing the love of women." }
  ],
  takeaway:"Genuine mourning honors even flawed leaders, and a believer refuses to gloat when a rival falls.",
  quiz:[
    { q:"Where was David living when the news of Saul's death reached him?", choices:["Jerusalem","Ziklag","Hebron","Gath"], a:1, why:"David had returned from fighting the Amalekites and had been in Ziklag two days when the messenger arrived (verses 1-2)." },
    { q:"How did David respond when he heard that Saul and Jonathan had fallen?", choices:["He celebrated that his rival was gone","He immediately marched to fight the Philistines","He tore his clothes, wept, and fasted until evening","He refused to believe the report"], a:2, why:"David and all the men with him rent their clothes, mourned, wept, and fasted until even for Saul, Jonathan, and the fallen people of the LORD (verses 11-12)." },
    { q:"Why did David order the messenger executed?", choices:["Because he lied about the battle's outcome","Because he was an Amalekite spy","Because he stole Saul's crown and bracelet","Because he admitted killing the LORD's anointed"], a:3, why:"David asked how the man was not afraid to destroy the LORD's anointed, and his own mouth testified against him (verses 14-16)." }
  ] },
{ n:2, summary:"David asks the LORD whether he should move, and on divine direction goes up to Hebron, where the men of Judah anoint him king. He blesses the men of Jabesh-gilead for burying Saul and invites them to stand with him. Meanwhile Abner, Saul's captain, installs Saul's son Ish-bosheth as king over the rest of Israel at Mahanaim, while David rules Judah from Hebron for seven years and six months. At the pool of Gibeon, twelve young men from each side kill one another in a contest that sparks a fierce battle; Abner is beaten. Asahel, Joab's fleet-footed brother, refuses Abner's repeated warnings to turn aside and is killed by the butt end of Abner's spear. Joab and Abishai pursue until Abner pleads for peace, and Joab blows the trumpet. David's side loses nineteen men plus Asahel; Abner's side loses three hundred sixty.",
  context:"Israel is split after Saul's death: David rules Judah from Hebron while Abner sets up Saul's son Ish-bosheth over the northern tribes from Mahanaim.",
  keyVerses:[
    { ref:"2 Samuel 2:1", text:"And it came to pass after this, that David inquired of the LORD, saying, Shall I go up into any of the cities of Judah? And the LORD said unto him, Go up." },
    { ref:"2 Samuel 2:4", text:"And the men of Judah came, and there they anointed David king over the house of Judah." },
    { ref:"2 Samuel 2:26", text:"Then Abner called to Joab, and said, Shall the sword devour for ever? knowest thou not that it will be bitterness in the latter end?" }
  ],
  takeaway:"David asked the LORD before moving; ambition that bypasses God turns kinsmen into casualties.",
  quiz:[
    { q:"Where was David anointed king over the house of Judah?", choices:["Jerusalem","Mahanaim","Hebron","Gibeon"], a:2, why:"The men of Judah came to Hebron and anointed David king over the house of Judah (verse 4)." },
    { q:"Why did Abner kill Asahel at the battle of Gibeon?", choices:["Asahel had insulted him at the pool","Ish-bosheth ordered it","Abner mistook him for a Philistine","Asahel refused to stop pursuing him"], a:3, why:"Abner warned Asahel twice to turn aside, but he would not, so Abner smote him with the hinder end of his spear (verses 21-23)." },
    { q:"What did Abner's plea at sunset, shall the sword devour for ever, teach about conflict?", choices:["Endless retaliation breeds bitterness and must be stopped","Battles should always continue until dawn","The winning side deserves total victory","Truces only work with written treaties"], a:0, why:"Abner asked how long the people would pursue their brethren, and Joab blew the trumpet so the fighting stopped (verses 26-28)." }
  ] },
{ n:3, summary:"The long war grinds on, but David grows stronger and Saul's house weaker, while six sons are born to David in Hebron. When Ish-bosheth accuses Abner of taking Saul's concubine Rizpah, Abner angrily defects, vowing to transfer the kingdom to David over all Israel. David agrees to meet him on one condition: bring Michal, the wife David had espoused long before for a hundred Philistine foreskins. Her tearful husband is sent away, and Abner canvasses the elders of Israel and Benjamin before coming to Hebron, where David feasts him and sends him away in peace. Joab returns from a raid, protests that Abner came only to spy, and secretly brings him back to murder him at the gate, revenge for his brother Asahel. David declares his innocence, mourns publicly at Abner's funeral, fasts until sunset, and laments that a prince and great man has fallen while the sons of Zeruiah are too hard for him.",
  context:"The dynastic stalemate breaks when Abner defects to David, and Joab's private revenge for his brother Asahel threatens to stain the peace.",
  keyVerses:[
    { ref:"2 Samuel 3:1", text:"Now there was long war between the house of Saul and the house of David: but David waxed stronger and stronger, and the house of Saul waxed weaker and weaker." },
    { ref:"2 Samuel 3:10", text:"To translate the kingdom from the house of Saul, and to set up the throne of David over Israel and over Judah, from Dan even to Beer-sheba." },
    { ref:"2 Samuel 3:39", text:"And I am this day weak, though anointed king; and these men the sons of Zeruiah be too hard for me: the LORD shall reward the doer of evil according to his wickedness." }
  ],
  takeaway:"Private vengeance destroys the peacemakers a nation needs; leaders must show they did not reward it.",
  quiz:[
    { q:"What did David require of Abner before making a league with him?", choices:["Surrender of Mahanaim","Ish-bosheth's abdication","Fifty talents of silver","That he bring Michal, David's wife"], a:3, why:"David would not see Abner's face except he first brought Michal, Saul's daughter, whom David had espoused for a hundred foreskins of the Philistines (verse 13)." },
    { q:"Why did Joab murder Abner at the gate of Hebron?", choices:["To avenge his brother Asahel, whom Abner killed at Gibeon","Because David secretly ordered it","Because Abner refused to feast with him","To stop Abner from joining the Philistines"], a:0, why:"Joab and Abishai slew Abner because he had slain their brother Asahel at Gibeon in the battle (verses 27, 30)." },
    { q:"What did David's public mourning for Abner accomplish?", choices:["It distracted from his alliance with Judah","It showed Israel the king was guiltless of Abner's blood","It forced Joab out of the army","It persuaded Ish-bosheth to surrender"], a:1, why:"David fasted, followed the bier, and lamented, and all the people understood that day that it was not of the king to slay Abner (verses 31-37)." }
  ] },
{ n:4, summary:"With Abner dead, Ish-bosheth's hands go feeble and all Israel is troubled. Two captains, Rechab and Baanah, sons of Rimmon the Beerothite, slip into the king's house at noon under pretense of fetching wheat and murder him in his bed, behead him, and carry the head through the night to David, presenting it as the LORD's vengeance on his enemy. David answers from his own history: he executed the Amalekite who claimed to have killed Saul, so how much more will he require the blood of men who slew a righteous person on his bed. He has the murderers put to death, their hands and feet hung up over the pool in Hebron, and Ish-bosheth's head buried in Abner's sepulchre. The chapter also introduces Mephibosheth, Jonathan's son, lame from a fall at age five, the last hope of Saul's house and soon to matter greatly.",
  context:"With Abner dead, Saul's remnant kingdom collapses from within, and David once more refuses to profit from blood brought to his door.",
  keyVerses:[
    { ref:"2 Samuel 4:4", text:"And Jonathan, Saul's son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth." },
    { ref:"2 Samuel 4:11", text:"How much more, when wicked men have slain a righteous person in his own house upon his bed? shall I not therefore now require his blood of your hand, and take you away from the earth?" }
  ],
  takeaway:"No worthy end ever justifies innocent blood; rewarding violence invites more of it.",
  quiz:[
    { q:"Which two captains murdered Ish-bosheth in his bedchamber?", choices:["Rechab and Baanah","Joab and Abishai","Zadok and Abiathar","Ahimaaz and Jonathan"], a:0, why:"Rechab and Baanah, the sons of Rimmon a Beerothite, came into the house as though to fetch wheat and smote him (verses 5-7)." },
    { q:"How did David reason when Rechab and Baanah brought him Ish-bosheth's head?", choices:["He rewarded them as avengers of his cause","He had executed the Amalekite who claimed to kill Saul, so these wicked murderers deserved death even more","He pardoned them but seized their land","He delayed judgment until the morning"], a:1, why:"David recalled slaying the one who brought tidings of Saul's death, and said how much more would he require the blood of men who slew a righteous person on his bed (verses 9-11)." },
    { q:"What does David's handling of Ish-bosheth's murderers teach about advancing a cause?", choices:["Ends are more important than means","Loyalty is proven by eliminating rivals","A righteous cause cannot be built on innocent blood","Kings should punish quickly without inquiry"], a:2, why:"David called Ish-bosheth a righteous person slain in his own house, and refused to let the deed benefit him (verses 9-12)." }
  ] },
{ n:5, summary:"All the tribes come to Hebron. They remind David that he led Israel's armies even under Saul and that the LORD appointed him to feed His people as captain; the elders make a league with him and anoint him king over Israel at age thirty. He reigns forty years, seven and a half over Judah in Hebron and thirty-three over all Israel and Judah in Jerusalem. His first campaign takes the Jebusite stronghold of Zion, which becomes the city of David; Hiram of Tyre builds him a house of cedar, and David perceives the LORD has established him for Israel's sake. When the Philistines twice deploy in the valley of Rephaim, David inquires of the LORD both times: first he breaks upon them like bursting waters at Baal-perazim, then, following the sound of a going in the mulberry trees, he strikes them from Geba all the way to Gazer.",
  context:"After seven and a half years over Judah, David is anointed over all Israel at Hebron, takes Jerusalem from the Jebusites, and beats back two Philistine invasions.",
  keyVerses:[
    { ref:"2 Samuel 5:2", text:"Also in time past, when Saul was king over us, thou wast he that leddest out and broughtest in Israel: and the LORD said to thee, Thou shalt feed my people Israel, and thou shalt be a captain over Israel." },
    { ref:"2 Samuel 5:7", text:"Nevertheless David took the strong hold of Zion: the same is the city of David." },
    { ref:"2 Samuel 5:12", text:"And David perceived that the LORD had established him king over Israel, and that he had exalted his kingdom for his people Israel's sake." }
  ],
  takeaway:"Inquire of the LORD before every advance, even after a victory, and credit Him when He answers.",
  quiz:[
    { q:"How old was David when he began to reign, and how long did he reign in all?", choices:["Twenty; twenty years","Thirty; forty years","Thirty-five; fifty years","Forty; forty years"], a:1, why:"David was thirty years old when he began to reign, and he reigned forty years (verse 4)." },
    { q:"In the second battle with the Philistines, how did the LORD direct David to fight?", choices:["Attack them head on at dawn","Circle around and burn their camp","Wait for the sound of a going in the tops of the mulberry trees, then bestir himself","Retreat to Hebron and defend the city"], a:2, why:"The LORD said to fetch a compass behind them, and when David heard the sound of a going in the mulberry trees, the LORD went out before him (verses 23-24)." },
    { q:"Why did David inquire of the LORD again before the second Philistine invasion, though he had just won?", choices:["Nathan required it by law","The elders of Israel demanded it","He feared losing his throne","Each new challenge deserved fresh direction from the LORD"], a:3, why:"David inquired both times the Philistines came, and the LORD gave a different answer each time, first Go up and then Thou shalt not go up (verses 19, 23)." }
  ] },
{ n:6, summary:"David gathers thirty thousand chosen men to bring the ark of God from Baale of Judah to Jerusalem on a new cart. When the oxen shake it at Nachon's threshingfloor, Uzzah steadies the ark with his hand and dies on the spot; David, displeased and afraid, abandons the journey and leaves the ark in the house of Obed-edom the Gittite, where the LORD blesses the whole household for three months. Hearing of it, David completes the move with gladness, sacrificing after every six paces and dancing before the LORD with all his might in a linen ephod. The ark is set in the tabernacle he pitched, offerings are made, and every person in the crowd receives bread, flesh, and a flagon of wine. Michal, Saul's daughter, despises the dancing king; David answers that he played before the LORD who chose him over her father's house, and Michal remains childless.",
  context:"With Jerusalem newly his capital, David brings the ark of the LORD into the city of David, learning both reverence and joy along the way.",
  keyVerses:[
    { ref:"2 Samuel 6:7", text:"And the anger of the LORD was kindled against Uzzah; and God smote him there for his error; and there he died by the ark of God." },
    { ref:"2 Samuel 6:11", text:"And the ark of the LORD continued in the house of Obed-edom the Gittite three months: and the LORD blessed Obed-edom, and all his household." },
    { ref:"2 Samuel 6:14", text:"And David danced before the LORD with all his might; and David was girded with a linen ephod." }
  ],
  takeaway:"Reverence comes first: celebrate the Lord's presence in the way He appoints, not merely the way that feels right.",
  quiz:[
    { q:"Where did the ark stay for three months after Uzzah's death?", choices:["The tabernacle at Gibeon","The house of Abinadab","The house of Obed-edom the Gittite","The fortress of Zion"], a:2, why:"David would not bring the ark into the city of David, so it continued in the house of Obed-edom, where the LORD blessed him and his household (verses 10-11)." },
    { q:"Why did David finally complete the move of the ark to Jerusalem?", choices:["Joab pressured him to try again","The Philistines threatened to steal it","The priests threatened to strike","He heard that the LORD had blessed Obed-edom's house because of the ark"], a:3, why:"When David was told the LORD had blessed Obed-edom and all that pertained to him because of the ark, he went and brought it up with gladness (verse 12)." },
    { q:"What lesson does Uzzah's death teach about approaching holy things?", choices:["The LORD's holiness calls for careful reverence, not casual handling, even with good intentions","Only kings may ever touch sacred furniture","The ark was too dangerous to keep in Israel","Oxen should never be used to pull carts"], a:0, why:"God smote Uzzah for his error when he took hold of the ark, and David went from displeasure to fear, asking how the ark of the LORD could come to him (verses 6-9)." }
  ] },
{ n:7, summary:"Settled in a house of cedar with the ark resting within curtains, David tells Nathan the prophet that he wants to build God a house. That night the word of the LORD reverses the plan: God never asked for one, took David from the sheepcote to be ruler over Israel, and will instead make David a house. David's seed will build the house for God's name; God will be his father, mercy will not depart as it did from Saul, and the throne shall be established for ever. Nathan reports the vision exactly as he received it. David sits before the LORD overwhelmed: who am I? He praises Israel's unrivaled God, recalls the redemption from Egypt, and asks the LORD to establish His word forever, so that the house of His servant David may be blessed forever.",
  context:"With the ark at rest in Jerusalem and enemies subdued, David's plan to build a temple draws out the LORD's promise of an everlasting house and throne.",
  keyVerses:[
    { ref:"2 Samuel 7:12", text:"And when thy days be fulfilled, and thou shalt sleep with thy fathers, I will set up thy seed after thee, which shall proceed out of thy bowels, and I will establish his kingdom." },
    { ref:"2 Samuel 7:16", text:"And thine house and thy kingdom shall be established for ever before thee: thy throne shall be established for ever." },
    { ref:"2 Samuel 7:18", text:"Then went king David in, and sat before the LORD, and he said, Who am I, O Lord GOD? and what is my house, that thou hast brought me hitherto?" }
  ],
  takeaway:"God often answers our plans to serve Him with a larger promise; humble prayer receives covenant blessings with gratitude.",
  quiz:[
    { q:"Which prophet did David consult about building a house for the ark?", choices:["Gad","Samuel","Abiathar","Nathan"], a:3, why:"The king said to Nathan the prophet that he dwelt in a house of cedar while the ark of God dwelt within curtains (verse 2)." },
    { q:"According to the LORD's message at night, who would build the house for His name?", choices:["David's seed, whom God would establish after him","Nathan the prophet","The elders of Israel","The Jebusites, as tribute"], a:0, why:"The LORD said He would set up David's seed after him, and he shall build an house for my name (verses 12-13)." },
    { q:"What promise did the LORD make about David's throne?", choices:["It would last only as long as Solomon obeyed","It would be established for ever","It would pass to Saul's descendants","It would end when David died"], a:1, why:"The LORD promised that David's house and kingdom would be established for ever before him, and his throne established for ever (verse 16)." }
  ] },
{ n:8, summary:"A survey of David's wars: he subdues the Philistines and takes Metheg-ammah, humbles Moab with a measuring line, and defeats Hadadezer of Zobah at the river Euphrates, houghing the chariot horses except enough for a hundred chariots. When the Syrians of Damascus come to Hadadezer's help, David slays twenty-two thousand of them, puts garrisons in Damascus, and the Syrians become servants bringing gifts; he also garrisons all Edom. The shields of gold from Hadadezer's servants and much brass from his cities come to Jerusalem, and when Toi king of Hamath sends his son Joram with vessels of silver, gold, and brass to congratulate David over their common enemy, David dedicates all of it to the LORD. Twice the chapter notes that the LORD preserved David whithersoever he went. It closes with David executing judgment and justice over all Israel, and names his officials from Joab the general to his own sons as chief rulers.",
  context:"A campaign survey of the young united kingdom: Moab, Zobah, Damascus, and Edom subdued, tribute dedicated to the LORD, and justice administered at home.",
  keyVerses:[
    { ref:"2 Samuel 8:6", text:"Then David put garrisons in Syria of Damascus: and the Syrians became servants to David, and brought gifts. And the LORD preserved David whithersoever he went." },
    { ref:"2 Samuel 8:11", text:"Which also king David did dedicate unto the LORD, with the silver and gold that he had dedicated of all nations which he subdued;" },
    { ref:"2 Samuel 8:15", text:"And David reigned over all Israel; and David executed judgment and justice unto all his people." }
  ],
  takeaway:"Strength is for service: victories are dedicated to the LORD and success is measured by judgment and justice for people.",
  quiz:[
    { q:"What did Toi king of Hamath send to David?", choices:["His son Joram with vessels of silver, gold, and brass","A thousand chariots","Cedar trees and masons","Seven hundred horsemen"], a:0, why:"Toi sent Joram his son to salute and bless David, since Hadadezer had wars with Toi, and Joram brought vessels of silver, gold, and brass (verses 9-10)." },
    { q:"What did David do with the silver and gold from the nations he subdued?", choices:["Built himself a new palace","Dedicated it unto the LORD","Divided it among his soldiers","Stored it in Hebron"], a:1, why:"King David dedicated the vessels Joram brought, together with the silver and gold of all the subdued nations, unto the LORD (verse 11)." },
    { q:"What marked David's reign at home according to verse 15?", choices:["Strict new taxation","Expansion of the standing army","He executed judgment and justice unto all his people","He shared power with Saul's family"], a:2, why:"David reigned over all Israel and executed judgment and justice unto all his people (verse 15)." }
  ] },
{ n:9, summary:"With the kingdom secure, David asks whether anyone of Saul's house survives so he can show kindness for Jonathan's sake. A former servant, Ziba, reports that Jonathan's son Mephibosheth, lame in both feet, lives at Lo-debar in the house of Machir. David sends for him, and the frightened man falls on his face. David calms his fear: he will show kindness for Jonathan's sake, restore all the land of Saul his father, and give him a permanent seat at the king's table. He then assigns Ziba, his fifteen sons, and his twenty servants to farm the land for Mephibosheth's support, while Mephibosheth himself eats at David's table like one of the king's sons. The chapter closes the loop: the man who hid in Lo-debar now dwells in Jerusalem, lame as ever, but provided for as family.",
  context:"Years after Saul's death, David seeks out the surviving grandson of his persecuted predecessor to honor the covenant of kindness made with Jonathan.",
  keyVerses:[
    { ref:"2 Samuel 9:1", text:"And David said, Is there yet any that is left of the house of Saul, that I may shew him kindness for Jonathan's sake?" },
    { ref:"2 Samuel 9:7", text:"And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy father's sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually." },
    { ref:"2 Samuel 9:13", text:"So Mephibosheth dwelt in Jerusalem: for he did eat continually at the king's table; and was lame on both his feet." }
  ],
  takeaway:"Covenant kindness outlives its moment; keeping a promise made years ago reflects the LORD's own loyalty.",
  quiz:[
    { q:"Where was Mephibosheth living when David sent for him?", choices:["Gibeah","Lo-debar, in the house of Machir","Mahanaim","Bethlehem"], a:1, why:"Ziba told the king that Jonathan's lame son was in the house of Machir, the son of Ammiel, in Lo-debar, and David fetched him from there (verses 4-5)." },
    { q:"Why did David show kindness to Mephibosheth?", choices:["To win the loyalty of Benjamin","Because Mephibosheth was a gifted commander","For Jonathan his father's sake","Because the law required restoring Saul's heirs"], a:2, why:"David said he would surely show kindness for Jonathan thy father's sake, restoring Saul's land and giving Mephibosheth a seat at his table (verse 7)." },
    { q:"What became Mephibosheth's standing in David's court?", choices:["A watched prisoner","A servant under Ziba","An exiled ward in Lo-debar","He ate bread at the king's table continually, as one of the king's sons"], a:3, why:"David said Mephibosheth would eat at his table as one of the king's sons, and he dwelt in Jerusalem eating continually at the king's table (verses 11, 13)." }
  ] },
{ n:10, summary:"When Nahash king of Ammon dies, David sends comforters to his son Hanun, remembering Nahash's kindness to him. Ammonite princes persuade Hanun the envoys are spies, so Hanun shaves off half of each man's beard and cuts their garments in the middle, sending them away humiliated; David has them wait at Jericho until their beards regrow. Realizing they have made an enemy, the Ammonites hire thousands of Syrian mercenaries. Joab finds Israel's army caught between Ammon at the gate and the Syrians in the field, splits the force with his brother Abishai, and promises they will back each other up: be of good courage, and the LORD do that which seemeth him good. Both enemies flee. The Syrians regroup under Hadarezer's captain Shobach, and David himself crosses Jordan and crushes them at Helam. The Syrian kings make peace with Israel and never help Ammon again.",
  context:"A courtesy embassy to new Ammonite king Hanun ends in humiliation and war, dragging David's armies into a two-front fight with Syrian mercenaries.",
  keyVerses:[
    { ref:"2 Samuel 10:2", text:"Then said David, I will shew kindness unto Hanun the son of Nahash, as his father shewed kindness unto me." },
    { ref:"2 Samuel 10:12", text:"Be of good courage, and let us play the men for our people, and for the cities of our God: and the LORD do that which seemeth him good." },
    { ref:"2 Samuel 10:19", text:"And when all the kings that were servants to Hadarezer saw that they were smitten before Israel, they made peace with Israel, and served them. So the Syrians feared to help the children of Ammon any more." }
  ],
  takeaway:"Do your duty with courage and leave outcomes to the LORD; that trust steadies an army caught between foes.",
  quiz:[
    { q:"How did Hanun humiliate David's messengers?", choices:["He imprisoned them for a year","He demanded a heavy tribute","He shaved off half their beards and cut their garments in the middle","He branded them as runaway slaves"], a:2, why:"Hanun took David's servants, shaved off the one half of their beards, and cut off their garments in the middle, sending them away (verse 4)." },
    { q:"How did Joab respond when the battle arrayed against him before and behind?", choices:["He retreated across Jordan","He waited for David to arrive","He sued for peace with the Syrians","He split the army with Abishai, each promising to help the other"], a:3, why:"Joab arrayed the choice men against the Syrians, gave the rest to Abishai against Ammon, and said if either was too strong, the other would come to help (verses 9-11)." },
    { q:"What does Joab's charge, the LORD do that which seemeth him good, reveal?", choices:["Courage and full trust in the LORD can go together","Victory was certain without divine help","Mercenaries fight better than patriots","Joab doubted the cause was just"], a:0, why:"Joab told the people to be of good courage and play the men for their people and the cities of their God, leaving the outcome to the LORD (verse 12)." }
  ] },
{ n:11, summary:"War season comes, but David stays in Jerusalem while Joab besieges Rabbah. From his roof he sees Bath-sheba, the wife of Uriah the Hittite; he sends for her, and she conceives. David recalls Uriah from the front, hoping he will go home, but Uriah refuses to enjoy his house while the ark, Israel, and Judah abide in tents. Even when David gets him drunk, Uriah still will not go down. So David sends him back carrying his own death warrant: set him in the forefront of the hottest battle and withdraw, that he may be smitten and die. Uriah falls in the fighting, and after her mourning Bath-sheba becomes David's wife and bears his son. The chapter closes with a single sentence of verdict: the thing that David had done displeased the LORD.",
  context:"At the peak of his power David stays home from the siege of Rabbah, and one desire leads through deception to the death of a loyal soldier.",
  keyVerses:[
    { ref:"2 Samuel 11:11", text:"And Uriah said unto David, The ark, and Israel, and Judah, abide in tents; and my lord Joab, and the servants of my lord, are encamped in the open fields; shall I then go into mine house, to eat and to drink, and to lie with my wife? as thou livest, and as thy soul liveth, I will not do this thing." },
    { ref:"2 Samuel 11:15", text:"And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die." },
    { ref:"2 Samuel 11:27", text:"And when the mourning was past, David sent and fetched her to his house, and she became his wife, and bare him a son. But the thing that David had done displeased the LORD." }
  ],
  takeaway:"Sin chosen in secret grows through cover-ups into ruin; the LORD sees what power tries to hide.",
  quiz:[
    { q:"Whose wife was Bath-sheba?", choices:["Joab's","Abner's","Eliam's","Uriah the Hittite's"], a:3, why:"When David inquired, he was told she was Bath-sheba, the daughter of Eliam, the wife of Uriah the Hittite (verse 3)." },
    { q:"Why did Uriah refuse to go down to his house?", choices:["The ark, Israel, and Judah abode in tents, and he would not enjoy his home while they campaigned","He was angry with his wife","He had vowed never to return home","He feared a trap set by Joab"], a:0, why:"Uriah answered that the ark, Israel, and Judah abode in tents while Joab and the servants encamped in open fields; he would not eat, drink, and lie with his wife (verse 11)." },
    { q:"How does the chapter's final sentence frame everything David did?", choices:["As a clever political success","As a thing that displeased the LORD","As an act hidden from heaven","As proof that ends justify the means"], a:1, why:"After Bath-sheba became David's wife and bore his son, the text states simply that the thing David had done displeased the LORD (verse 27)." }
  ] },
{ n:12, summary:"The LORD sends Nathan with a parable: a rich man with many flocks steals and cooks the one little ewe lamb of a poor man rather than his own. David, enraged, pronounces the thief deserving of death and fourfold restitution, and Nathan answers, thou art the man. Through Nathan the LORD recounts all He gave David, names his sins against Uriah, and declares judgment: the sword will never depart from David's house, and evil will rise against him from his own family, done openly because the sin was done secretly. David confesses, I have sinned against the LORD, and receives pardon even as consequences begin: the child falls sick and dies despite David's fasting. David rises, worships, and eats, saying he will go to the child but the child will not return to him. Solomon is then born to Bath-sheba, whom the LORD loves, and David completes the capture of Rabbah, whose royal crown ends on his head.",
  context:"Nathan the prophet confronts the king with a parable that exposes the sin against Uriah; pardon and painful consequences arrive side by side.",
  keyVerses:[
    { ref:"2 Samuel 12:7", text:"And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;" },
    { ref:"2 Samuel 12:13", text:"And David said unto Nathan, I have sinned against the LORD. And Nathan said unto David, The LORD also hath put away thy sin; thou shalt not die." },
    { ref:"2 Samuel 12:23", text:"But now he is dead, wherefore should I fast? can I bring him back again? I shall go to him, but he shall not return to me." }
  ],
  takeaway:"Confession meets mercy, but forgiven sin still carries consequences; no one is above the LORD's correction.",
  quiz:[
    { q:"In Nathan's parable, what did the rich man take from the poor man?", choices:["His one little ewe lamb","His harvest","His servants","His house"], a:0, why:"The poor man had nothing but one little ewe lamb, which the rich man took and dressed for his traveller instead of using his own flock (verses 3-4)." },
    { q:"What judgment did the LORD pronounce through Nathan?", choices:["David would lose the kingdom immediately","The sword would never depart from David's house, and evil would rise against him from his own family","David would die within the year","Bath-sheba would be sent back to her family"], a:1, why:"Because David despised the commandment of the LORD and killed Uriah, the sword would never depart his house, and the LORD would raise up evil against him out of his own house (verses 10-11)." },
    { q:"How did the LORD respond to David's confession, I have sinned against the LORD?", choices:["Nathan refused to speak to him again","The sentence of death fell on David instead","The LORD put away his sin, so he would not die, though consequences still followed","The sin was overlooked entirely"], a:2, why:"Nathan said the LORD had put away David's sin and he would not die, yet the child born to him still fell sick and died (verses 13-14, 18)." }
  ] },
{ n:13, summary:"Amnon, David's heir, is obsessed with his half sister Tamar and, coached by his cousin Jonadab, feigns illness to get her alone in his chamber. He refuses her plea not to force her, overpowers her, and then, despising what he has done, throws her out and bolts the door. Tamar puts ashes on her head and cries out; Absalom takes her into his house, and David, hearing everything, is very wroth but does nothing. Two years later Absalom avenges her at a sheepshearing feast near Baal-hazor: when Amnon's heart is merry with wine, Absalom's servants kill him at his signal. A report that all the king's sons are dead proves false, but Absalom flees to his grandfather Talmai, king of Geshur, and stays three years while David mourns Amnon and then longs to go forth to the banished Absalom.",
  context:"The sword prophesied against David's house begins to fall within his own family, as private violence goes unpunished and ripens into murder.",
  keyVerses:[
    { ref:"2 Samuel 13:12", text:"And she answered him, Nay, my brother, do not force me; for no such thing ought to be done in Israel: do not thou this folly." },
    { ref:"2 Samuel 13:21", text:"But when king David heard of all these things, he was very wroth." },
    { ref:"2 Samuel 13:39", text:"And the soul of king David longed to go forth unto Absalom: for he was comforted concerning Amnon, seeing he was dead." }
  ],
  takeaway:"Unpunished wrongdoing multiplies: what leaders refuse to address in one generation consumes the next.",
  quiz:[
    { q:"Who counseled Amnon how to get Tamar alone?", choices:["Absalom","Jonadab, his cousin","Joab","Ahithophel"], a:1, why:"Jonadab, the son of Shimeah David's brother, a very subtil man, told Amnon to feign sickness and ask that Tamar come dress meat before him (verses 3-5)." },
    { q:"Where did Absalom flee after Amnon's death, and how long did he stay?", choices:["To Bethlehem for two years","To Gath for one year","To Geshur, to king Talmai, for three years","To the wilderness of Judah for forty days"], a:2, why:"Absalom fled to Talmai the son of Ammihud, king of Geshur, and was there three years (verses 37-38)." },
    { q:"What did David's anger without action contribute to in this chapter?", choices:["A lasting peace in his family","Tamar's full restoration","Amnon's repentance","Absalom's brooding hatred and Amnon's murder"], a:3, why:"David was very wroth but did nothing; Absalom spoke to Amnon neither good nor bad for two years while hatred ripened into murder (verses 21-22, 28-29)." }
  ] },
{ n:14, summary:"Joab sees the king softening toward Absalom and stages a case at court. A wise woman of Tekoah, coached by Joab, presents herself as a widow whose one surviving son faces blood vengeance from her clan for killing his brother. David grants her protection, and she turns the case: why, when the king has just saved her banished son, does he keep his own banished one from returning? We must needs die, she says, as water spilt on the ground that cannot be gathered up; yet God deviseth means, that his banished be not expelled from him. David detects Joab's hand, and Absalom is brought from Geshur, though for two more years he may not see the king's face. Finally, after burning Joab's barley field to force a meeting, Absalom gets his audience, bows himself to the ground, and the king kisses his son.",
  context:"Absalom waits in exile at Geshur while Joab works the court through a hired advocate, and the king's half-pardon stretches into years of distance.",
  keyVerses:[
    { ref:"2 Samuel 14:14", text:"For we must needs die, and are as water spilt on the ground, which cannot be gathered up again; neither doth God respect any person: yet doth he devise means, that his banished be not expelled from him." },
    { ref:"2 Samuel 14:24", text:"And the king said, Let him turn to his own house, and let him not see my face. So Absalom returned to his own house, and saw not the king's face." },
    { ref:"2 Samuel 14:33", text:"So Joab came to the king, and told him: and when he had called for Absalom, he came to the king, and bowed himself on his face to the ground before the king: and the king kissed Absalom." }
  ],
  takeaway:"Pardon from a distance is not reconciliation; restored relationships need honest, personal repair.",
  quiz:[
    { q:"Who put the words in the wise woman of Tekoah's mouth?", choices:["David","Nathan","Joab","Zadok"], a:2, why:"Joab fetched the woman from Tekoah, told her to feign herself a mourner, and put the words in her mouth (verses 2-3)." },
    { q:"What was the woman's key argument for bringing the banished home?", choices:["Absalom had paid the blood price","The army threatened mutiny","The Philistines demanded it","We must needs die, yet God deviseth means that his banished be not expelled from him"], a:3, why:"The woman argued that the king, by sparing her son, condemned himself for not fetching home his banished, since God deviseth means that the banished be not expelled (verses 13-14)." },
    { q:"Even after Absalom returned, what still blocked true reconciliation for two years?", choices:["He was not allowed to see the king's face","He refused to leave his own house","Joab kept them apart for profit","Tamar's family forbade the meeting"], a:0, why:"The king said Absalom should turn to his own house and not see his face, and so it remained for two full years until Absalom forced the issue (verses 24, 28, 32-33)." }
  ] },
{ n:15, summary:"Absalom builds a following at Jerusalem's gate, sympathizing with every petitioner and sighing that the king assigns no one to hear them; he kisses those who bow to him, and so steals the hearts of the men of Israel. Under cover of a vowed offering in Hebron he raises revolt, sending trumpets through the tribes with the cry, Absalom reigneth, with two hundred unwitting guests and David's own counselor Ahithophel at his side. Told that the hearts of the men of Israel are with his son, David chooses flight over a siege of Jerusalem, leaving ten concubines to keep the house. Loyal Ittai the Gittite vows to follow him in death or life; the priests Zadok and Abiathar carry the ark back to the city to become his eyes. David climbs Olivet weeping, barefoot, praying that Ahithophel's counsel turn to foolishness, and meets Hushai, whom he sends in as a counter-spy.",
  context:"Absalom's charm campaign at the city gate turns national affection, and David chooses exile over a war that would destroy his own capital.",
  keyVerses:[
    { ref:"2 Samuel 15:6", text:"And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel." },
    { ref:"2 Samuel 15:21", text:"And Ittai answered the king, and said, As the LORD liveth, and as my lord the king liveth, surely in what place my lord the king shall be, whether in death or life, even there also will thy servant be." },
    { ref:"2 Samuel 15:31", text:"And one told David, saying, Ahithophel is among the conspirators with Absalom. And David said, O LORD, I pray thee, turn the counsel of Ahithophel into foolishness." }
  ],
  takeaway:"Flattery can steal a crowd's heart, but tested loyalty and prayer outlast a conspiracy.",
  quiz:[
    { q:"Where did Absalom stage the beginning of his revolt?", choices:["Jerusalem","Gath","Bahurim","Hebron"], a:3, why:"Absalom asked leave to pay a vow in Hebron, went there, and had trumpets blown with the cry, Absalom reigneth in Hebron (verses 7-10)." },
    { q:"Why did David flee Jerusalem instead of defending it?", choices:["To keep Absalom from smiting the city with the edge of the sword","Because the army had mutinied","Because the Philistines invaded","Zadok advised retreat"], a:0, why:"David told his servants to make speed to depart, lest Absalom overtake them suddenly, bring evil upon them, and smite the city with the edge of the sword (verse 14)." },
    { q:"What did Ittai the Gittite's pledge, whether in death or life, demonstrate?", choices:["Mercenaries are unreliable in a crisis","Loyal friendship proves itself in a leader's darkest hour","Foreigners should avoid civil wars","David had bought Ittai's service"], a:1, why:"Though David urged the newcomer Ittai to return to his place, Ittai swore by the LORD to stay with the king in death or life (verses 19-21)." }
  ] },
{ n:16, summary:"Ziba meets David with provisions and a story: Mephibosheth stayed in Jerusalem hoping to reclaim Saul's kingdom. David grants Ziba all his master's estate. At Bahurim a Saulide named Shimei hurls stones and curses, calling David a bloody man whose fall is the LORD's doing; Abishai wants his head, but David refuses: his own son seeks his life, how much more this Benjamite. Perhaps the LORD will look on his affliction and requite good for the cursing. Meanwhile Absalom occupies Jerusalem. Hushai appears before him with feigned loyalty, saying he will serve whomever the LORD and the people choose, and is accepted. Ahithophel's first counsel is calculated: Absalom shall go in to his father's concubines on the housetop, in the sight of all Israel, so that the breach is beyond repair. The chapter notes that Ahithophel's counsel counted as if a man had inquired at the oracle of God.",
  context:"The road of exile tests David's humility through Ziba's flattery and Shimei's curses, while Jerusalem falls and Ahithophel's counsel guides Absalom.",
  keyVerses:[
    { ref:"2 Samuel 16:11", text:"And David said to Abishai, and to all his servants, Behold, my son, which came forth of my bowels, seeketh my life: how much more now may this Benjamite do it? let him alone, and let him curse; for the LORD hath bidden him." },
    { ref:"2 Samuel 16:12", text:"It may be that the LORD will look on mine affliction, and that the LORD will requite me good for his cursing this day." },
    { ref:"2 Samuel 16:23", text:"And the counsel of Ahithophel, which he counselled in those days, was as if a man had inquired at the oracle of God: so was all the counsel of Ahithophel both with David and with Absalom." }
  ],
  takeaway:"Under unjust attack, humility leaves room for the LORD to requite; revenge belongs to Him, not to us.",
  quiz:[
    { q:"Who cursed David and threw stones at him at Bahurim?", choices:["Shimei the son of Gera","Ziba the servant of Mephibosheth","Abner's brother","Ittai the Gittite"], a:0, why:"Shimei, the son of Gera, a man of the family of the house of Saul, came out at Bahurim cursing and casting stones as David passed (verses 5-6)." },
    { q:"Why did David let Shimei continue cursing?", choices:["He was too weary to respond","He believed the LORD had bidden him, and the LORD might requite good for the cursing","Abishai persuaded him to forgive","He did not hear the insults"], a:1, why:"David said, let him alone, and let him curse; for the LORD hath bidden him, adding that the LORD might look on his affliction and requite him good (verses 11-12)." },
    { q:"What does Hushai's mission teach about answering wicked counsel?", choices:["Evil counsel cannot be resisted","Prayer can be answered through a faithful friend placed to defeat bad advice","Counselors should always flee with the king","Absalom was easy to deceive because he was evil"], a:2, why:"David prayed that Ahithophel's counsel be turned to foolishness, then sent Hushai back to speak so as to defeat that counsel (15:31; 16:16-19)." }
  ] },
{ n:17, summary:"Ahithophel proposes a swift night raid with twelve thousand men to strike the king only while he is weary and weak-handed. Absalom seeks a second opinion, and Hushai argues the opposite: David and his men are mighty and chafed like a bear robbed of her whelps, and a rushed strike that loses men at the first could panic all Israel. Better to gather all Israel from Dan to Beer-sheba, with Absalom at the head in person. The council prefers Hushai, for the LORD had appointed to defeat the good counsel of Ahithophel, to the intent that the LORD might bring evil upon Absalom. Hushai warns the priests, who send their sons Jonathan and Ahimaaz; the pair barely escapes discovery in a covered well at Bahurim and reaches David with the word: cross Jordan tonight. David's company crosses by morning; the rejected Ahithophel goes home and hangs himself; and at Mahanaim, Shobi, Machir, and Barzillai bring the hungry army food.",
  context:"Two rival counsels decide the revolt, and the LORD stands behind the weaker one, buying David time to cross Jordan and regroup at Mahanaim.",
  keyVerses:[
    { ref:"2 Samuel 17:14", text:"And Absalom and all the men of Israel said, The counsel of Hushai the Archite is better than the counsel of Ahithophel. For the LORD had appointed to defeat the good counsel of Ahithophel, to the intent that the LORD might bring evil upon Absalom." },
    { ref:"2 Samuel 17:23", text:"And when Ahithophel saw that his counsel was not followed, he saddled his ass, and arose, and gat him home to his house, to his city, and put his household in order, and hanged himself, and died, and was buried in the sepulchre of his father." },
    { ref:"2 Samuel 17:29", text:"And honey, and butter, and sheep, and cheese of kine, for David, and for the people that were with him, to eat: for they said, The people is hungry, and weary, and thirsty, in the wilderness." }
  ],
  takeaway:"The LORD governs outcomes beyond human wisdom, often answering prayer through loyal friends in the right places.",
  quiz:[
    { q:"What did Ahithophel do when Absalom rejected his counsel?", choices:["Defected to David","Raised his own army","Fled to Egypt","Saddled his ass, went home, and hanged himself"], a:3, why:"When Ahithophel saw his counsel was not followed, he went home, put his household in order, hanged himself, died, and was buried in his father's sepulchre (verse 23)." },
    { q:"Why did Hushai advise Absalom to gather all Israel rather than strike at once?", choices:["He claimed David's men were chafed like a bear robbed of her whelps and a rushed attack could backfire","The mercenaries demanded more pay","Ahithophel was too sick to lead","The elders wanted time to negotiate peace"], a:0, why:"Hushai argued that David and his men were mighty and chafed in their minds like a bear robbed of her whelps, so an early setback would embolden all Israel against Absalom (verses 8-10)." },
    { q:"What does verse 14 reveal about why Hushai's counsel prevailed?", choices:["Absalom feared Ahithophel","The LORD had appointed to defeat the good counsel of Ahithophel","Hushai bribed the elders","Ahithophel spoke too quietly"], a:1, why:"The text says the LORD had appointed to defeat the good counsel of Ahithophel, to the intent that the LORD might bring evil upon Absalom (verse 14)." }
  ] },
{ n:18, summary:"David organizes his force into thirds under Joab, Abishai, and Ittai; the people talk the king out of going out with them, saying he is worth ten thousand of them, and he stands at the gate commanding the captains: deal gently for my sake with the young man Absalom. In the wood of Ephraim twenty thousand fall, the forest devouring more than the sword. Absalom, riding a mule, is caught by the head in the thick boughs of a great oak, hanging between heaven and earth. A soldier refuses to touch him for fear of the king's charge, but Joab thrusts three darts through his heart, and ten young men that bare Joab's armour finish him; his body is cast into a pit under a great heap of stones. Joab checks the eager runner Ahimaaz, and it falls to Cushi to tell David of the victory and his son's death. David goes up over the gate weeping: O my son Absalom, would God I had died for thee.",
  context:"The civil war ends in the forest of Ephraim, where Absalom dies against his father's orders and the king's grief nearly swallows the victory.",
  keyVerses:[
    { ref:"2 Samuel 18:5", text:"And the king commanded Joab and Abishai and Ittai, saying, Deal gently for my sake with the young man, even with Absalom. And all the people heard when the king gave all the captains charge concerning Absalom." },
    { ref:"2 Samuel 18:9", text:"And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away." },
    { ref:"2 Samuel 18:33", text:"And the king was much moved, and went up to the chamber over the gate, and wept: and as he went, thus he said, O my son Absalom, my son, my son Absalom! would God I had died for thee, O Absalom, my son, my son!" }
  ],
  takeaway:"Even deserved consequences can be carried with a father's grief; victory and mourning are not strangers.",
  quiz:[
    { q:"What happened to Absalom during the battle in the wood of Ephraim?", choices:["He was captured and imprisoned","He escaped to Geshur again","His mule carried him under an oak, his head caught fast, and Joab slew him","He fell at the gate of Mahanaim"], a:2, why:"Absalom's mule went under the thick boughs of a great oak and he was taken up between heaven and earth; Joab took three darts and thrust them through his heart (verses 9, 14)." },
    { q:"Why did the soldier refuse to strike Absalom even for a reward?", choices:["He owed Absalom a debt","He feared the Philistines would avenge him","He could not tell him from a common servant","The king had charged the captains, beware that none touch the young man Absalom"], a:3, why:"The man said he would not put forth his hand against the king's son, for the king had charged Joab, Abishai, and Ittai in their hearing (verses 5, 12)." },
    { q:"What does David's cry, would God I had died for thee, reveal?", choices:["A father's love persists even toward a rebellious child","He regretted winning the battle","He planned to abdicate the throne","He blamed Joab openly"], a:0, why:"Much moved, David went up over the gate weeping and wished he himself had died instead of Absalom, his son, his son (verse 33)." }
  ] },
{ n:19, summary:"The victory turns to mourning as the army steals home ashamed, and Joab bluntly rebukes the king: you have shamed your servants who saved your life; go out and speak comfortably to them, or not one man will stay with you tonight. David sits in the gate, and the tribes, remembering all he delivered them from and that Absalom is dead in battle, argue over bringing the king back. David works through the priests to move Judah first, offering Amasa the command of the host, and Judah comes to Gilgal to escort him over. Shimei meets the king pleading mercy and receives an oath that he will not die, over Abishai's objection. Mephibosheth explains that Ziba deceived him, and lets him keep the divided land. Eighty-year-old Barzillai declines a place at court in Jerusalem, sending his son Chimham instead. The chapter ends with Judah and Israel quarreling over who honors the king most.",
  context:"David crosses back over Jordan pardoning enemies, thanking friends, and negotiating with tribes and elders for a reunited kingdom.",
  keyVerses:[
    { ref:"2 Samuel 19:7", text:"Now therefore arise, go forth, and speak comfortably unto thy servants: for I swear by the LORD, if thou go not forth, there will not tarry one with thee this night:" },
    { ref:"2 Samuel 19:22", text:"And David said, What have I to do with you, ye sons of Zeruiah, that ye should this day be adversaries unto me? shall there any man be put to death this day in Israel? for do not I know that I am this day king over Israel?" },
    { ref:"2 Samuel 19:23", text:"Therefore the king said unto Shimei, Thou shalt not die. And the king sware unto him." }
  ],
  takeaway:"Restoration is the hour for mercy and gratitude, not for settling old scores.",
  quiz:[
    { q:"Who rebuked David for shaming his servants with his mourning?", choices:["Abishai","Zadok","Barzillai","Joab"], a:3, why:"Joab told the king he had shamed the faces of all his servants who saved his life that day, and warned him to go forth and speak comfortably to them (verses 5-7)." },
    { q:"Why did David spare Shimei, who had cursed him on the flight from Jerusalem?", choices:["This was a day of restoration, and he swore that Shimei would not die","Shimei proved Saul was innocent","Shimei brought the ark back","The law forbade punishing Benjamites"], a:0, why:"David asked whether any man should be put to death this day in Israel, since he knew he was king over Israel, and swore to Shimei he would not die (verses 22-23)." },
    { q:"What did Barzillai's refusal of reward teach about service?", choices:["Kindness should always be repaid in full","Faithful service seeks no palace comforts in return","Old men make poor counselors","Hospitality deserves a government post"], a:1, why:"Barzillai, eighty years old, asked why he should be a burden to the king, and asked instead that Chimham go over with David (verses 34-37)." }
  ] },
{ n:20, summary:"A troublemaker named Sheba son of Bichri blows a trumpet, crying that Israel has no part in David, every man to his tents, and Israel abandons the king again while Judah clings to him. Home in Jerusalem, David confines the ten concubines who had kept his house, keeping them in widowhood for life. He orders Amasa to muster Judah in three days; when Amasa is late, David sends Abishai after Sheba, and Joab joins the march. At the great stone in Gibeon, Joab greets Amasa with a kiss and kills him with a sword that fell from its sheath, resuming command of the pursuit. Sheba is besieged in Abel of Beth-maachah, where a wise woman challenges Joab, asking why he would swallow up the inheritance of the LORD, and negotiates the city's deliverance by throwing Sheba's severed head over the wall. The revolt dissolves, Joab returns to Jerusalem, and the chapter closes with the king's officers listed.",
  context:"The kingdom's unity is still fragile: one Benjamite's revolt, an assassinated general, and a besieged city all in the weeks after David's return.",
  keyVerses:[
    { ref:"2 Samuel 20:1", text:"And there happened to be there a man of Belial, whose name was Sheba, the son of Bichri, a Benjamite: and he blew a trumpet, and said, We have no part in David, neither have we inheritance in the son of Jesse: every man to his tents, O Israel." },
    { ref:"2 Samuel 20:19", text:"I am one of them that are peaceable and faithful in Israel: thou seekest to destroy a city and a mother in Israel: why wilt thou swallow up the inheritance of the LORD?" },
    { ref:"2 Samuel 20:22", text:"Then the woman went unto all the people in her wisdom. And they cut off the head of Sheba the son of Bichri, and cast it out to Joab. And he blew a trumpet, and they retired from the city, every man to his tent. And Joab returned to Jerusalem unto the king." }
  ],
  takeaway:"One reckless voice can divide a nation, but calm wisdom can end what only war otherwise settles.",
  quiz:[
    { q:"Whose cry was, we have no part in David, every man to his tents, O Israel?", choices:["Sheba the son of Bichri","Amasa","Shimei","Mephibosheth"], a:0, why:"Sheba, the son of Bichri, a Benjamite described as a man of Belial, blew a trumpet and called Israel away from David (verse 1)." },
    { q:"How was the siege of Abel of Beth-maachah resolved?", choices:["Joab stormed the walls at dawn","A wise woman negotiated, and the city threw Sheba's head over the wall","David granted the city a treaty","Sheba escaped by night"], a:1, why:"A wise woman cried out to Joab, went to all the people in her wisdom, and they cut off Sheba's head and cast it over the wall, ending the siege (verses 16-22)." },
    { q:"What did the wise woman's plea, thou seekest to destroy a city and a mother in Israel, accomplish?", choices:["It delayed the siege for weeks","It provoked the city to resist longer","It turned a whole city's fate from destruction to deliverance through calm negotiation","It convinced Joab to spare Amasa"], a:2, why:"The woman called Abel a peaceable and faithful city, a mother in Israel, and her negotiation delivered it: Joab said deliver him only, and I will depart (verses 19-21)." }
  ] },
{ n:21, summary:"Three straight years of famine lead David to inquire of the LORD, who answers that Saul's bloody assault on the Gibeonites, a people Israel had sworn to spare, is the cause. David asks the Gibeonites what atonement they require; they refuse silver or blood from Israel generally, but ask that seven of Saul's descendants be hanged before the LORD at Gibeah. David hands over Rizpah's two sons by Saul and five sons of Saul's house, but spares Mephibosheth for the LORD's oath between him and Jonathan. Rizpah keeps a lonely vigil over the hanged bodies from harvest until water drops from heaven, and when David hears of it he gathers the bones of Saul and Jonathan from Jabesh-gilead and buries them honorably in the sepulchre of Kish in Benjamin; after that God was entreated for the land. Four battles with Philistine giants follow, in which David grows faint and his men swear to keep him home, lest he quench the light of Israel.",
  context:"A three-year famine is traced to an old wrong against the Gibeonites, and renewed Philistine wars remind Israel that David can no longer fight alone.",
  keyVerses:[
    { ref:"2 Samuel 21:1", text:"Then there was a famine in the days of David three years, year after year; and David inquired of the LORD. And the LORD answered, It is for Saul, and for his bloody house, because he slew the Gibeonites." },
    { ref:"2 Samuel 21:14", text:"And the bones of Saul and Jonathan his son buried they in the country of Benjamin in Zelah, in the sepulchre of Kish his father: and they performed all that the king commanded. And after that God was entreated for the land." },
    { ref:"2 Samuel 21:17", text:"But Abishai the son of Zeruiah succoured him, and smote the Philistine, and killed him. Then the men of David sware unto him, saying, Thou shalt go no more out with us to battle, that thou quench not the light of Israel." }
  ],
  takeaway:"When trouble lingers, seek the LORD's answer and make past injustice right; broken covenants keep costing.",
  quiz:[
    { q:"What cause did the LORD give David for the three-year famine?", choices:["David's recent census","Saul's slaying of the Gibeonites","Joab's war in Edom","The neglect of the ark"], a:1, why:"When David inquired of the LORD, the answer was that the famine was for Saul and his bloody house, because he slew the Gibeonites (verse 1)." },
    { q:"Why was Mephibosheth spared when Saul's other descendants were handed over?", choices:["He had joined David's army","He was hidden by Ziba","Because of the LORD's oath between David and Jonathan","The Gibeonites had never named him"], a:2, why:"The king spared Mephibosheth, the son of Jonathan, because of the LORD's oath that was between David and Jonathan the son of Saul (verse 7)." },
    { q:"After the bones of Saul and Jonathan were honorably buried, what does the text say happened?", choices:["David built a new palace","Rizpah was rewarded with land","The Gibeonites left Israel","God was entreated for the land"], a:3, why:"The bones were buried in the sepulchre of Kish in Zelah, and after that God was entreated for the land (verse 14)." }
  ] },
{ n:22, summary:"David sings the LORD the words of this song on the day the LORD delivered him out of the hand of all his enemies, and out of the hand of Saul. It opens with titles, rock, fortress, deliverer, shield, horn of salvation, high tower, then recalls distress: waves of death, snares of hell, until his cry entered God's ears. The answer shakes creation: the earth trembles, the LORD bows the heavens, rides upon a cherub, thunders, and scatters enemies with arrows and lightning; He draws David out of many waters because He delights in him. David sings that the LORD repaid him according to his righteousness and the cleanness of his hands, that God shows Himself merciful to the merciful and upright to the upright, and that the afflicted He saves while bringing down the haughty. The song ends where its trust began: the LORD liveth, blessed be my rock, who shows mercy to His anointed, to David and his seed for evermore.",
  context:"A retrospective hymn, composed when the LORD had delivered him from every enemy including Saul, reviews David's life as one long answered prayer.",
  keyVerses:[
    { ref:"2 Samuel 22:2", text:"And he said, The LORD is my rock, and my fortress, and my deliverer;" },
    { ref:"2 Samuel 22:31", text:"As for God, his way is perfect; the word of the LORD is tried: he is a buckler to all them that trust in him." },
    { ref:"2 Samuel 22:47", text:"The LORD liveth; and blessed be my rock; and exalted be the God of the rock of my salvation." }
  ],
  takeaway:"Deliverance deserves singing: rehearsing the LORD's rescues turns memory into praise and fresh trust.",
  quiz:[
    { q:"What images does David use for the LORD at the song's opening?", choices:["Shepherd, vine, bread","Sun, moon, stars","Rock, fortress, deliverer","River, garden, tower"], a:2, why:"David began, The LORD is my rock, and my fortress, and my deliverer, adding shield, horn of salvation, high tower, and refuge (verses 2-3)." },
    { q:"What occasioned this song, according to its heading?", choices:["His anointing at Hebron","The birth of Solomon","The bringing of the ark to Jerusalem","The day the LORD delivered him out of the hand of all his enemies, and out of the hand of Saul"], a:3, why:"David spake these words in the day that the LORD had delivered him out of the hand of all his enemies, and out of the hand of Saul (verse 1)." },
    { q:"What does the song say God is to all who trust in Him?", choices:["A buckler; his way is perfect and his word is tried","A silent observer of events","A rewarder of the haughty","A distant judge hard to reach"], a:0, why:"The song declares that God's way is perfect, his word is tried, and he is a buckler to all them that trust in him; the afflicted he saves, but the haughty he brings down (verses 28, 31)." }
  ] },
{ n:23, summary:"David's last words come as inspired testimony: the Spirit of the LORD spake by me, and his word was in my tongue. The Rock of Israel taught him that he that ruleth over men must be just, ruling in the fear of God, shining like morning light after rain; and though his house be not so with God, He has made with him an everlasting covenant, ordered in all things and sure. Then come the mighty men. Adino lifted his spear against eight hundred at one time; Eleazar fought until his hand clave unto the sword, the LORD working a great victory; Shammah defended a field of lentiles alone. Three of the thirty broke through the Philistine host to draw water from Bethlehem's well for the thirsty king, who poured it out unto the LORD, counting it the blood of men who jeopardized their lives. Benaiah slew a lion in a pit on a snowy day, and the roll of the Thirty ends with Uriah the Hittite: thirty-seven in all.",
  context:"David's closing testimony and the roll call of his mighty men, Uriah the Hittite among them, honor the people who built his reign.",
  keyVerses:[
    { ref:"2 Samuel 23:3", text:"The God of Israel said, the Rock of Israel spake to me, He that ruleth over men must be just, ruling in the fear of God." },
    { ref:"2 Samuel 23:5", text:"Although my house be not so with God; yet he hath made with me an everlasting covenant, ordered in all things, and sure: for this is all my salvation, and all my desire, although he make it not to grow." },
    { ref:"2 Samuel 23:16", text:"And the three mighty men brake through the host of the Philistines, and drew water out of the well of Beth-lehem, that was by the gate, and took it, and brought it to David: nevertheless he would not drink thereof, but poured it out unto the LORD." }
  ],
  takeaway:"Just rule shines like morning light; it rests on God's sure covenant and honors the people who carry the work.",
  quiz:[
    { q:"What did David do with the water his three mighty men drew from the well of Bethlehem?", choices:["He drank it at once","He shared it with the Thirty","He stored it in the tabernacle","He poured it out unto the LORD"], a:3, why:"David would not drink the water from Bethlehem's well, but poured it out unto the LORD (verse 16)." },
    { q:"Why would David not drink the water?", choices:["He counted it as the blood of the men who went in jeopardy of their lives","It had spoiled on the journey","He was under a vow against drinking","Nathan forbade drinking well water"], a:0, why:"David said, be it far from me, O LORD, that I should do this: is not this the blood of the men that went in jeopardy of their lives? (verse 17)." },
    { q:"According to David's last words, what must characterize one who rules over men?", choices:["Wealth and a strong army","Justice, ruling in the fear of God","Popular approval at the gate","Victories in foreign wars"], a:1, why:"The Rock of Israel taught David that he that ruleth over men must be just, ruling in the fear of God (verse 3)." }
  ] },
{ n:24, summary:"The LORD's anger burns against Israel, and David is moved to number the people. Joab protests, asking why his lord delights in this, but the king's word prevails, and after nine months and twenty days the count stands at eight hundred thousand valiant men that drew the sword in Israel and five hundred thousand in Judah. David's heart smites him: I have sinned greatly and done very foolishly. Through the seer Gad the LORD offers a choice of punishments, seven years famine, three months of flight before enemies, or three days of pestilence, and David chooses to fall into the hand of the LORD, whose mercies are great. Seventy thousand die before the angel stays at the threshingfloor of Araunah the Jebusite. David takes the guilt on himself, asking what these sheep have done. At Gad's direction he buys the threshingfloor, refusing Araunah's free gift because he will not offer that which costs him nothing, builds an altar, and the plague is stayed.",
  context:"The book closes with a census that brings judgment, a choice that trusts the LORD's mercies, and an altar on newly purchased ground where the plague stops.",
  keyVerses:[
    { ref:"2 Samuel 24:14", text:"And David said unto Gad, I am in a great strait: let us fall now into the hand of the LORD; for his mercies are great: and let me not fall into the hand of man." },
    { ref:"2 Samuel 24:17", text:"And David spake unto the LORD when he saw the angel that smote the people, and said, Lo, I have sinned, and I have done wickedly: but these sheep, what have they done? let thine hand, I pray thee, be against me, and against my father's house." },
    { ref:"2 Samuel 24:24", text:"And the king said unto Araunah, Nay; but I will surely buy it of thee at a price: neither will I offer burnt offerings unto the LORD my God of that which doth cost me nothing. So David bought the threshingfloor and the oxen for fifty shekels of silver." }
  ],
  takeaway:"Real worship costs something; owning sin and pleading for others is a leader's place before the LORD.",
  quiz:[
    { q:"How long did Joab and the captains take to number the people?", choices:["Nine months and twenty days","Three years","Forty days and forty nights","Seven months"], a:0, why:"After going through all the land, they came to Jerusalem at the end of nine months and twenty days (verse 8)." },
    { q:"Why did David choose three days of pestilence over the other options?", choices:["It was the shortest punishment","He preferred to fall into the hand of the LORD, whose mercies are great, rather than into the hand of man","Gad commanded that option","Famine would have emptied the storehouses"], a:1, why:"David said he was in a great strait: let us fall now into the hand of the LORD, for his mercies are great, and let me not fall into the hand of man (verse 14)." },
    { q:"Why did David insist on buying Araunah's threshingfloor?", choices:["Araunah asked too high a price for a gift","The law forbade gifts from Jebusites","He would not offer burnt offerings unto the LORD of that which doth cost him nothing","The altar required purchased stone"], a:2, why:"Though Araunah offered the oxen and wood freely, David said he would surely buy it at a price, for he would not offer that which cost him nothing (verses 22-24)." }
  ] }
);
